class Solution:
    def permute(self, nums: list[int]) -> list[list[int]]:
        ans = []
        path = []

        def choose():
            if len(path) == len(nums):
                ans.append(path[:])
                return

            for num in nums:
                if num in path:
                    continue
                path.append(num)
                choose()
                path.pop()

        choose()
        return ans
